from pathlib import Path
import json,html,re,math
from datetime import date
ROOT=Path(__file__).resolve().parents[1]
BASE='https://aitraineracademy.online'
GA_TAG='<!-- Google tag (gtag.js) -->\n<script async src="https://www.googletagmanager.com/gtag/js?id=G-82S9M9TYKR"></script>\n<script>\n  window.dataLayer = window.dataLayer || [];\n  function gtag(){dataLayer.push(arguments);}\n  gtag(\'js\', new Date());\n  gtag(\'config\', \'G-82S9M9TYKR\');\n</script>\n'
categories=json.loads((ROOT/'blog/categories.json').read_text())
category_by_name={c['name']:c for c in categories}
def category_url(name): return '/blog/'+category_by_name[name]['slug']+'/'
def esc(x): return html.escape(str(x),quote=True)
def write(path,s):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def page(title,desc,path,body,article=None):
 schema={'@context':'https://schema.org','@type':'BlogPosting' if article else 'WebPage','headline':title,'description':desc,'url':BASE+path,'publisher':{'@type':'Organization','name':'AI Trainer Academy','url':BASE}}
 current_category=next((c for c in categories if path==category_url(c['name'])),None)
 if current_category:
  schema['@type']='CollectionPage'
  schema['mainEntity']={'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'url':BASE+'/blog/'+q['slug']+'/','name':q['title']} for i,q in enumerate([q for q in posts if q['category']==current_category['name']])]}
 schema['publisher']['logo']={'@type':'ImageObject','url':BASE+'/assets/logo.webp'}
 schema['inLanguage']='pt-BR'
 schema['image']=BASE+'/blog/assets/social.webp'
 if article: schema.update(datePublished=article['date'],dateModified=article.get('updated',article['date']),author={'@type':'Organization','name':'Equipe AI Trainer Academy','url':BASE+'/blog/editorial/'},mainEntityOfPage=BASE+path)
 crumbs=[('Início','/'),('Blog','/blog/')]
 if article: crumbs.append((article['category'],category_url(article['category'])))
 if path!='/blog/':
  if '/ferramentas/' in path and path!='/blog/ferramentas/': crumbs.append(('Ferramentas gratuitas','/blog/ferramentas/'))
  crumbs.append((title,path))
 breadcrumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':BASE+u} for i,(n,u) in enumerate(crumbs)]}
 category_nav='<nav class="category-nav" aria-label="Categorias do blog"><div class="wrap">'+''.join('<a href="'+category_url(c['name'])+'"'+(' aria-current="page"' if path==category_url(c['name']) else '')+'>'+esc(c['name'])+'</a>' for c in categories)+'</div></nav>'
 trail='<nav class="breadcrumbs wrap" aria-label="Caminho da página">'+'<span aria-hidden="true"> / </span>'.join(f'<a href="{u}">{esc(n) if len(n)<46 else esc(n[:43])+"…"}</a>' for n,u in crumbs)+'</nav>'
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | AI Trainer Academy</title><meta name="description" content="{esc(desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#0c2230"><link rel="canonical" href="{BASE+path}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{BASE+path}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:locale" content="pt_BR"><meta property="og:image" content="{BASE}/blog/assets/social.webp"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Blog AI Trainer Academy — Trabalho com IA"><meta name="twitter:card" content="summary_large_image"><link rel="alternate" type="application/rss+xml" title="Blog AI Trainer Academy" href="/blog/feed.xml"><link rel="icon" href="/assets/logo.webp"><link rel="stylesheet" href="/blog/blog.css"><script type="application/ld+json">{json.dumps([schema,breadcrumb],ensure_ascii=False).replace('<',chr(92)+'u003c')}</script>{GA_TAG}</head><body><a class="skip" href="#principal">Ir para o conteúdo</a><header class="top"><div class="wrap nav"><a class="brand" href="/blog/"><img src="/assets/logo.webp" width="1100" height="440" alt="AI Trainer Academy"><span>BLOG & RECURSOS</span></a><nav aria-label="Principal"><a href="/blog/treinamento-de-ia/">Treinamento de IA</a><a href="/blog/renda-com-ia-em-casa/">Renda com IA em Casa</a><a href="/blog/ferramentas/">Ferramentas grátis</a></nav></div>{category_nav}</header><main id="principal">{trail}{body}</main><footer><div class="wrap"><strong>AI Trainer Academy · Blog</strong><p>Guias de treinamento de IA e tarefas de coleta de dados em casa.</p><a href="/blog/editorial/">Sobre e política editorial</a><a href="/#radar">Conhecer o Radar</a><a href="/">Conhecer o treinamento</a><a href="/renda-com-ia-em-casa/">Renda com IA em Casa</a><p>Conteúdo educativo independente. Não somos representantes das plataformas citadas. Oportunidades, aprovação e renda dependem de cada projeto.</p></div></footer></body></html>'''
def hero(k,t,d): return f'<section class="hero"><div class="hero-grid" aria-hidden="true"></div><div class="wrap"><div class="eyebrow">{k}</div><h1>{t}</h1><p>{d}</p></div></section>'
def cta(product=None):
 if product=='renda-casa': return '<section class="section wrap"><div class="cta"><div><div class="eyebrow" style="color:#83ead1">Renda com IA em Casa</div><h2>Prepare sua próxima tarefa com um processo claro.</h2><p>Aprenda a ler requisitos, preparar o ambiente, gravar, revisar e acompanhar seus envios. Curso independente, sem garantia de tarefas ou rendimentos.</p></div><a class="btn" href="/renda-com-ia-em-casa/?utm_source=blog&amp;utm_medium=organic&amp;utm_campaign=renda_casa">Conhecer o curso ↗</a></div></section>'
 return '<section class="section wrap"><div class="cta"><div><div class="eyebrow" style="color:#83ead1">Seu próximo passo</div><h2>Transforme informação em preparação.</h2><p>Organize sua busca, fortaleça currículo e LinkedIn e pratique avaliações com o treinamento da AI Trainer Academy. Conheça também o Radar de Oportunidades.</p></div><a class="btn" href="/?utm_source=blog&utm_medium=organic&utm_campaign=artigos#oferta">Conhecer o método ↗</a></div></section>'
posts=json.loads((ROOT/'blog/posts.json').read_text())
assert len({p['slug'] for p in posts})==len(posts)
for p in posts:
 assert re.fullmatch('[a-z0-9-]+',p['slug'])
 assert p['category'] in category_by_name
 assert p['slug'] not in {c['slug'] for c in categories}|{'editorial','ferramentas'}
 assert not re.search(r'<\s*(script|iframe)|\bon\w+\s*=|javascript:',p['body'],re.I)
 for s in p['sources']:assert s['url'].startswith('https://')
 paths=[]
 for i,m in enumerate(re.finditer(r'<h2>(.*?)</h2>',p['body'])): paths.append((f's{i}',m.group(1)))
 body=p['body']
 for ident,label in paths:body=body.replace(f'<h2>{label}</h2>',f'<h2 id="{ident}">{label}</h2>',1)
 minutes=max(1,math.ceil(len(re.sub('<[^>]+>',' ',body).split())/200))
 sources='<h2 id="fontes">Fontes e verificação</h2><ul>'+''.join(f'<li><a href="{esc(s["url"])}" rel="noopener">{esc(s["title"])}</a></li>' for s in p['sources'])+'</ul><p class="meta">Fontes consultadas em '+esc(p.get('updated',p['date']))+'. Exemplos são autorais e didáticos. Produzido com apoio de IA segundo nossa <a href="/blog/editorial/">política editorial</a>.</p>'
 related='<h2>Continue sua preparação</h2><ul>'+''.join(f'<li><a href="/blog/{q["slug"]}/">{esc(q["title"])}</a></li>' for q in sorted(posts,key=lambda q:(q['category']==p['category'],q['date']),reverse=True)[:7] if q!=p)+'</ul>'
 nav='<aside class="sidebar"><nav aria-label="Neste artigo"><strong>NESTE GUIA</strong>'+''.join(f'<a href="#{a}">{b}</a>' for a,b in paths)+'<a href="#fontes">Fontes</a></nav></aside>'
 body=hero('<a href="'+category_url(p['category'])+'">'+esc(p['category'])+'</a>',esc(p['title']),esc(p['description']))+f'<div class="section wrap article-layout"><article class="prose"><p class="meta">Equipe AI Trainer Academy · {p["date"]} · {minutes} min de leitura</p>'+body+sources+related+'</article>'+nav+'</div>'+cta(p.get('product'))
 write(f'blog/{p["slug"]}/index.html',page(p['title'],p['description'],f'/blog/{p["slug"]}/',body,p))
def render_card(p,i):
 return f'<article class="card" data-category="{esc(p["category"])}" data-search="{esc((p["title"]+" "+p["description"]+" "+p["category"]).lower())}"><div class="card-art" aria-hidden="true"><span>0{i+1}↗</span><small>GUIA PRÁTICO<br>AI TRAINER ACADEMY</small></div><div class="card-body"><div class="eyebrow"><a href="{category_url(p["category"])}">{esc(p["category"])}</a></div><h3><a href="/blog/{p["slug"]}/">{esc(p["title"])}</a></h3><p>{esc(p["description"])}</p><a class="more" href="/blog/{p["slug"]}/">Ler o guia ↗</a></div></article>'
cards=''.join(render_card(p,i) for i,p in enumerate(sorted(posts,key=lambda p:p['date'],reverse=True)))
for category in categories:
 grouped=[p for p in posts if p['category']==category['name']]
 assert grouped,category['name']
 category_body=hero('Explore por tema',esc(category['title']),esc(category['description']))+'<section class="section wrap"><div class="category-intro prose"><h2>O que você encontra aqui</h2><p>'+esc(category['intro'])+'</p><div class="note">'+esc(category['action'])+'</div></div><div class="section-head"><h2>Guias desta categoria</h2><span class="meta">'+str(len(grouped))+(' guia' if len(grouped)==1 else ' guias')+'</span></div><div class="grid category-articles">'+''.join(render_card(p,i) for i,p in enumerate(grouped))+'</div><div class="category-explore"><h2>Continue por outro tema</h2>'+''.join('<a href="'+category_url(c['name'])+'">'+esc(c['name'])+' ↗</a>' for c in categories if c!=category)+'</div></section>'+cta('renda-casa' if category['slug']=='renda-com-ia-em-casa' else None)
 write('blog/'+category['slug']+'/index.html',page(category['title'],category['description'],category_url(category['name']),category_body))
toolcards='''<div class="grid"><article class="tool-card"><div class="eyebrow">01 · Prática guiada</div><h3>Você sabe avaliar uma resposta de IA?</h3><p>Compare respostas em três exercícios autorais e entenda o raciocínio por trás de cada escolha.</p><a href="/blog/ferramentas/treino-avaliacao/">Experimentar o treino ↗</a></article><article class="tool-card"><div class="eyebrow">02 · Organização</div><h3>Checklist antes da candidatura</h3><p>Confira fonte, requisitos e documentos. Saia com uma lista clara do que ainda precisa verificar.</p><a href="/blog/ferramentas/checklist-candidatura/">Abrir meu checklist ↗</a></article></div>'''
index=hero('Blog · Trabalho humano por trás da IA','Trabalho humano com IA.<br><em>Escolha seu próximo passo.</em>','Explore dois caminhos: treinamento e avaliação de IA ou tarefas de coleta de dados em casa. Guias práticos para se preparar e conferir cada oportunidade.')+'<div class="editorial-strip"><div class="wrap"><span>✦ GUIAS COM FONTES OFICIAIS</span><span>EXEMPLOS AUTORAIS</span><span>FERRAMENTAS SEM CADASTRO</span></div></div><section class="section wrap"><div class="section-head"><h2>Da curiosidade à prática.</h2><a href="/blog/editorial/">Como produzimos nossos guias ↗</a></div><div class="filters"><label for="search" class="skip">Buscar artigos</label><input id="search" type="search" placeholder="Qual é a sua dúvida?"><label for="category" class="skip">Categoria</label><select id="category"><option value="">Todos os temas</option>'+''.join(f'<option>{esc(c)}</option>' for c in sorted({p['category'] for p in posts}))+'</select></div><p id="count" class="meta" aria-live="polite"></p><div class="grid" id="articles">'+cards+'</div><p id="empty" hidden>Nenhum artigo encontrado. Tente outra palavra ou categoria.</p></section><section class="tools section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Ferramentas gratuitas</div><h2>Aprenda fazendo.</h2></div><p>Sem cadastro. Direto ao ponto.</p></div>'+toolcards+'</div></section>'+cta()+'<script src="/blog/search.js" defer></script>'
write('blog/index.html',page('Blog: treinamento de IA e tarefas em casa','Guias, exemplos e ferramentas gratuitas para buscar projetos de treinamento de IA, preparar candidaturas e praticar avaliações.','/blog/',index))
training=[p for p in posts if p.get('product')!='renda-casa']
training_body=hero('Treinamento de IA','Prepare seu perfil.<br><em>Pratique a avaliação.</em>','Guias sobre carreira, currículo, candidaturas e comparação de respostas de IA.')+'<section class="section wrap"><div class="category-explore">'+''.join('<a href="'+category_url(c['name'])+'">'+esc(c['name'])+' ↗</a>' for c in categories if c['slug']!='renda-com-ia-em-casa')+'</div><div class="grid category-articles">'+''.join(render_card(p,i) for i,p in enumerate(training))+'</div></section>'+cta()
write('blog/treinamento-de-ia/index.html',page('Treinamento de IA: carreira, candidaturas e prática','Guias para preparar seu perfil profissional e praticar avaliação de respostas de IA.','/blog/treinamento-de-ia/',training_body))
write('blog/ferramentas/index.html',page('Ferramentas gratuitas para futuros avaliadores de IA','Pratique avaliações de respostas e prepare suas candidaturas com ferramentas gratuitas, sem cadastro.','/blog/ferramentas/',hero('Ferramentas grátis','Menos teoria.<br><em>Mais prática.</em>','Recursos autorais para experimentar o trabalho e organizar o próximo passo, sem cadastro.')+'<section class="section wrap">'+toolcards+'</section>'+cta()))
editorial='''<h2>Quem publica</h2><p>Este é o blog da AI Trainer Academy, marca responsável pelo treinamento e pelo Radar de Oportunidades apresentados neste site. Publicamos guias sobre treinamento e avaliação de IA e sobre tarefas de coleta de dados em casa. Também comercializamos o curso Renda com IA em Casa, apresentado nas chamadas desta área. Temos interesse comercial na venda desses produtos e sinalizamos as chamadas para conhecê-los.</p><h2>Como produzimos</h2><p>Usamos IA na pesquisa, redação e revisão, com critérios editoriais definidos pela equipe. Isso não significa que cada publicação passou por revisão humana individual. Cada guia deve apresentar fontes, exemplos autorais e uma ação prática. Não reproduzimos testes de seleção, tarefas confidenciais ou materiais internos de empresas.</p><h2>Verificação e atualizações</h2><p>Requisitos, países aceitos, remuneração e etapas precisam ser conferidos nas fontes oficiais. Não tratamos uma página institucional como comprovação de vaga aberta. Quando uma informação não está confirmada, ela deve ser omitida ou identificada como pendente. A data de publicação e a data de atualização indicam o histórico do texto; não alteramos datas sem revisão do conteúdo.</p><h2>Independência e resultados</h2><p>As marcas citadas pertencem aos respectivos titulares. O curso é uma formação independente, não uma contratação, representação ou garantia de aprovação. Exemplos e exercícios públicos são educativos. A compra do curso não é requisito para candidatar-se nas plataformas.</p><h2>Ferramentas e privacidade</h2><p>Os exercícios funcionam no navegador e não enviam respostas a um servidor. O checklist pode ser salvo neste navegador, se o armazenamento estiver disponível. Não insira documentos, senhas ou informações confidenciais. Use o botão de limpar para apagar o checklist salvo.</p><h2>Correções</h2><p>Encontrou uma informação desatualizada? Use o canal de contato indicado no rodapé da <a href="/">página oficial da AI Trainer Academy</a> e informe o endereço do artigo e a fonte da correção.</p>'''
write('blog/editorial/index.html',page('Sobre o blog e política editorial','Conheça os critérios de pesquisa, uso de IA, fontes e transparência comercial do Blog AI Trainer Academy.','/blog/editorial/',hero('Transparência editorial','Conhecimento com<br><em>fonte e contexto.</em>','Como produzimos, verificamos e atualizamos os conteúdos do blog.')+'<section class="section wrap"><article class="prose" style="max-width:760px">'+editorial+'</article></section>'))
for slug,title,desc,inside in [
 ('treino-avaliacao','Treino gratuito de avaliação de respostas de IA','Pratique comparação de respostas em exercícios autorais com explicações.', '<p>Três exercícios didáticos. Não são testes de nenhuma plataforma e não preveem aprovação em seleções.</p><div id="quiz"><p id="step" class="eyebrow"></p><h2 id="prompt"></h2><div id="choices"></div><div id="feedback" class="feedback" aria-live="polite"></div><button id="next" class="btn" type="button" hidden>Próximo exercício →</button><button id="restart" type="button" class="btn" hidden>Praticar novamente</button></div><noscript>Ative o JavaScript para usar o treino. Você também pode ler nossos guias de preparação.</noscript><script src="/blog/quiz.js" defer></script>'),
 ('checklist-candidatura','Checklist gratuito antes de se candidatar a projetos de IA','Confira os requisitos e organize as pendências antes de enviar sua candidatura.', '<p>Marque apenas o que você realmente conferiu. O resultado mostra seu progresso nesta lista; não mede elegibilidade nem chance de aprovação.</p><div id="checks"></div><p id="status" aria-live="polite"></p><progress id="progress" max="8" value="0" aria-label="Itens conferidos"></progress><div class="feedback"><button type="button" id="download" class="btn">Baixar minhas pendências</button> <button type="button" id="clear">Limpar checklist</button></div><p class="meta" id="storage-note">Os itens são salvos somente neste navegador, quando disponível. Não insira dados pessoais.</p><noscript>Ative o JavaScript para marcar os itens e baixar suas pendências.</noscript><script src="/blog/checklist.js" defer></script>')]:
 write(f'blog/ferramentas/{slug}/index.html',page(title,desc,f'/blog/ferramentas/{slug}/',hero('Ferramenta gratuita · Sem cadastro',title,desc)+'<section class="wrap"><div class="tool-box">'+inside+'</div></section>'+cta()))
urls=['/','/blog/treinamento-de-ia/','/blog/','/blog/editorial/','/blog/ferramentas/','/blog/ferramentas/treino-avaliacao/','/blog/ferramentas/checklist-candidatura/']+[category_url(c['name']) for c in categories]+[f'/blog/{p["slug"]}/' for p in posts]
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE+u}</loc>'+ (f'<lastmod>{next(p.get("updated",p["date"]) for p in posts if u=="/blog/"+p["slug"]+"/")}</lastmod>' if any(u=="/blog/"+p["slug"]+"/" for p in posts) else '')+'</url>' for u in urls)+'</urlset>')
write('robots.txt','User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
print(f'Built {len(posts)} articles, index, editorial, 2 tools and sitemap.')

from xml.sax.saxutils import escape as xml_escape
from email.utils import formatdate
from datetime import datetime,timezone
feed='<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>Blog AI Trainer Academy</title><link>'+BASE+'/blog/</link><description>Preparação para projetos de treinamento e avaliação de IA</description><language>pt-BR</language>'
for post in sorted(posts,key=lambda x:x['date'],reverse=True):
 url=BASE+'/blog/'+post['slug']+'/'
 stamp=datetime.strptime(post['date'],'%Y-%m-%d').replace(tzinfo=timezone.utc).timestamp()
 feed+='<item><title>'+xml_escape(post['title'])+'</title><link>'+url+'</link><guid isPermaLink="true">'+url+'</guid><description>'+xml_escape(post['description'])+'</description><pubDate>'+formatdate(stamp,usegmt=True)+'</pubDate></item>'
write('blog/feed.xml',feed+'</channel></rss>')
